import SwiftUI
import UIKit

public struct AZOrderedListItem: Identifiable, Equatable {
    public var id: String { userID }
    public let userID: String
    public let avatarURL: String?
    public let title: String?
    public let extraData: Any?
    public init(userID: String, avatarURL: String? = nil, title: String? = nil, extraData: Any? = nil) {
        self.userID = userID
        self.avatarURL = avatarURL
        self.title = title
        self.extraData = extraData
    }

    public static func == (lhs: AZOrderedListItem, rhs: AZOrderedListItem) -> Bool {
        return lhs.id == rhs.id
    }
}

private struct GroupedAZOrderedListItem {
    let sectionTitle: String
    let users: [AZOrderedListItem]
}

private struct SystemIndexBar: UIViewRepresentable {
    @EnvironmentObject var themeState: ThemeState
    let sectionTitles: [String]
    let onSectionSelected: (String) -> Void
    func makeUIView(context: Context) -> UIView {
        let containerView = UIView()
        containerView.backgroundColor = UIColor.clear
        let tableView = UITableView()
        tableView.backgroundColor = UIColor.clear
        tableView.separatorStyle = .none
        tableView.isScrollEnabled = false
        tableView.showsVerticalScrollIndicator = false
        tableView.translatesAutoresizingMaskIntoConstraints = false
        tableView.sectionIndexColor = UIColor(themeState.colors.textColorLink)
        tableView.sectionIndexBackgroundColor = UIColor.clear
        tableView.dataSource = context.coordinator
        tableView.delegate = context.coordinator
        containerView.addSubview(tableView)
        NSLayoutConstraint.activate([
            tableView.topAnchor.constraint(equalTo: containerView.topAnchor),
            tableView.bottomAnchor.constraint(equalTo: containerView.bottomAnchor),
            tableView.trailingAnchor.constraint(equalTo: containerView.trailingAnchor),
            tableView.leadingAnchor.constraint(equalTo: containerView.leadingAnchor)
        ])
        context.coordinator.tableView = tableView
        context.coordinator.sectionTitles = sectionTitles
        context.coordinator.onSectionSelected = onSectionSelected
        return containerView
    }

    func updateUIView(_ uiView: UIView, context: Context) {
        context.coordinator.sectionTitles = sectionTitles
        context.coordinator.onSectionSelected = onSectionSelected
        context.coordinator.tableView?.sectionIndexColor = UIColor(themeState.colors.textColorLink)
        context.coordinator.tableView?.reloadData()
    }

    func makeCoordinator() -> Coordinator {
        Coordinator()
    }

    class Coordinator: NSObject, UITableViewDataSource, UITableViewDelegate {
        var tableView: UITableView?
        var sectionTitles: [String] = []
        var onSectionSelected: ((String) -> Void)?


        func numberOfSections(in tableView: UITableView) -> Int {
            return sectionTitles.count
        }

        func tableView(_ tableView: UITableView, numberOfRowsInSection section: Int) -> Int {
            return 1
        }

        func tableView(_ tableView: UITableView, cellForRowAt indexPath: IndexPath) -> UITableViewCell {
            let cell = UITableViewCell()
            cell.backgroundColor = UIColor.clear
            cell.selectionStyle = .none
            cell.textLabel?.text = ""
            return cell
        }


        func tableView(_ tableView: UITableView, heightForRowAt indexPath: IndexPath) -> CGFloat {
            return 14
        }

        func tableView(_ tableView: UITableView, heightForHeaderInSection section: Int) -> CGFloat {
            return 0
        }

        func tableView(_ tableView: UITableView, heightForFooterInSection section: Int) -> CGFloat {
            return 0
        }


        func sectionIndexTitles(for tableView: UITableView) -> [String]? {
            return sectionTitles
        }

        func tableView(_ tableView: UITableView, sectionForSectionIndexTitle title: String, at index: Int) -> Int {
            onSectionSelected?(title)
            return index
        }
    }
}

public struct AZOrderedListView: View {
    @EnvironmentObject var themeState: ThemeState
    @State private var groupedUsers: [GroupedAZOrderedListItem] = []
    @State private var sectionTitles: [String] = []
    @State private var scrollTarget: String?
    @State private var sectionScrollOffset: CGFloat = 0
    @State private var scrubbingLetter: String? = nil
    let userList: [AZOrderedListItem]
    let header: AnyView?
    let footer: AnyView?
    let onItemClick: (AZOrderedListItem) -> Void
    let config: AZOrderedListConfig
    let emptyText: String?
    let onUserInteraction: (() -> Void)?
    private static var pinyinCache: [Character: String] = [:]
    private static let maxCacheSize = 1000

    public init(
        userList: [AZOrderedListItem],
        header: AnyView? = nil,
        footer: AnyView? = nil,
        config: AZOrderedListConfig? = nil,
        emptyText: String? = nil,
        onUserInteraction: (() -> Void)? = nil,
        onItemClick: @escaping (AZOrderedListItem) -> Void
    ) {
        self.userList = userList
        self.header = header
        self.footer = footer
        self.config = config ?? AZOrderedListConfig()
        self.emptyText = emptyText
        self.onUserInteraction = onUserInteraction
        self.onItemClick = onItemClick
    }

    public var body: some View {
        ZStack(alignment: .trailing) {
            ScrollViewReader { proxy in
                ScrollView {
                    // 标记须位于非懒加载容器的首个分组处，避免离屏卸载丢失滚动偏移。
                    VStack(spacing: 0) {
                        if let header = header {
                            header
                        }
                        Color.clear
                            .frame(height: 0)
                            .scrollOffsetMarker(coordinateSpace: "AZOrderedListScroll") { minY in
                                sectionScrollOffset = -minY
                            }
                        LazyVStack(spacing: 0) {
                            ForEach(Array(groupedUsers.enumerated()), id: \.offset) { _, group in
                                VStack(spacing: 0) {
                                    if self.config.showIndexBar {
                                        Text(group.sectionTitle)
                                            .font(themeState.fonts.caption2Bold)
                                            .foregroundColor(themeState.colors.textColorPrimary)
                                            .padding(.horizontal, CGFloat(SpacingScheme.bubbleSpacing))
                                            .frame(maxWidth: .infinity, alignment: .leading)
                                            .frame(height: 32)
                                            .background(themeState.colors.bgColorInput)
                                    }
                                    ForEach(group.users) { user in
                                        AZOrderedListCell(
                                            user: user,
                                            showsDivider: user.id != group.users.last?.id,
                                            onItemClick: {
                                                onUserInteraction?()
                                                onItemClick(user)
                                            }
                                        )
                                    }
                                }
                                // 分组 ID 须设置在 ForEach 直接子视图，否则离屏分组无法定位。
                                .id(group.sectionTitle)
                            }
                        }
                        // 复用分组 ID 时内容更新可能不传播，使用内容指纹重建列表。
                        .id(groupedUsers.map { "\($0.sectionTitle)|" + $0.users.map { "\($0.id)#\($0.title ?? "")" }.joined(separator: ".") }.joined(separator: "/"))
                        if let footer = footer {
                            footer
                        }
                    }
                }
                .scrollDismissesKeyboardCompat()
                .coordinateSpace(name: "AZOrderedListScroll")
                .simultaneousGesture(DragGesture(minimumDistance: 8).onChanged { _ in onUserInteraction?() })
                .onAppear {
                    DispatchQueue.main.async {
                        processUserList()
                    }
                }
                .onChange(of: userList) { newUserList in
                    DispatchQueue.main.async {
                        self.processUserListWithData(newUserList)
                    }
                }
                .onChange(of: scrollTarget) { target in
                    if let target = target {
                        withAnimation(.easeInOut(duration: 0.3)) {
                            proxy.scrollTo(target, anchor: .top)
                        }
                        scrollTarget = nil
                    }
                }
                .onReceive(NotificationCenter.default.publisher(for: UIApplication.didBecomeActiveNotification)) { _ in
                    processUserList()
                }
            }
            if groupedUsers.isEmpty {
                emptyView
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                    .allowsHitTesting(false)
            }
            if config.showIndexBar && !sectionTitles.isEmpty && !groupedUsers.isEmpty {
                LetterIndexBar(
                    sectionTitles: sectionTitles,
                    onLetterSelected: { sectionTitle in
                        scrollTarget = sectionTitle
                    },
                    scrubbingLetter: $scrubbingLetter,
                    currentLetter: currentLetter
                )
                .padding(.trailing, CGFloat(SpacingScheme.smallSpacing))
                .zIndex(1)
            }
            if let scrubbing = scrubbingLetter {
                LetterIndexCenterBubble(letter: scrubbing)
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                    .zIndex(2)
            }
        }
        .background(themeState.colors.bgColorOperate)
        .onAppear {
            if groupedUsers.isEmpty {
                DispatchQueue.main.async { processUserList() }
            }
        }
    }

    private var currentLetter: String? {
        visibleSectionLetter(
            atScrollOffset: sectionScrollOffset,
            orderedLetters: sectionTitles,
            sectionRowCounts: groupedUsers.map { $0.users.count }
        )
    }

    private var emptyView: some View {
        VStack(spacing: CGFloat(SpacingScheme.iconIconSpacing)) {
            Image("uikit_empty_illustration", bundle: AtomicXChatResources.resourceBundle)
                .resizable()
                .scaledToFit()
                .frame(width: 88, height: 88 * 300.0 / 338.0)
            Text(emptyText ?? LocalizedChatString("NoUser"))
                .font(themeState.fonts.caption2Regular)
                .foregroundColor(themeState.colors.textColorTertiary)
                .multilineTextAlignment(.center)
                .padding(.horizontal, CGFloat(SpacingScheme.bubbleSpacing))
        }
    }

    private func processUserList() {
        processUserListWithData(userList)
    }

    private func processUserListWithData(_ users: [AZOrderedListItem]) {
        let currentUserListHash = users.map { "\($0.id)-\($0.title ?? "")" }.joined(separator: ",")
        let currentGroupedHash = groupedUsers.flatMap { $0.users }.map { "\($0.id)-\($0.title ?? "")" }.joined(separator: ",")

        if currentUserListHash == currentGroupedHash && !groupedUsers.isEmpty {
            return
        }

        let sortedUsers = users.sorted { user1, user2 in
            let title1 = user1.title ?? user1.id
            let title2 = user2.title ?? user2.id
            return title1.localizedCaseInsensitiveCompare(title2) == .orderedAscending
        }
        var groupedDict: [String: [AZOrderedListItem]] = [:]
        for user in sortedUsers {
            let title = user.title ?? user.id
            let sectionTitle = PinyinIndexHelper.sectionLetter(for: title)
            if groupedDict[sectionTitle] == nil {
                groupedDict[sectionTitle] = []
            }
            groupedDict[sectionTitle]?.append(user)
        }
        let sortedSections = groupedDict.keys.sorted { section1, section2 in
            sortSections(section1, section2)
        }
        let newGroupedUsers = sortedSections.map { sectionTitle in
            GroupedAZOrderedListItem(sectionTitle: sectionTitle, users: groupedDict[sectionTitle] ?? [])
        }

        groupedUsers = newGroupedUsers
        sectionTitles = sortedSections
    }

    private func getFirstCharacter(_ text: String) -> String {
        guard let firstChar = text.first else { return "#" }
        let unicodeValue = firstChar.unicodeScalars.first?.value ?? 0
        if unicodeValue >= 0x4E00 && unicodeValue <= 0x9FFF {
            return getChinesePinyinFirstLetter(String(firstChar))
        }
        if (firstChar >= "A" && firstChar <= "Z") || (firstChar >= "a" && firstChar <= "z") {
            return String(firstChar).uppercased()
        }
        if firstChar.isNumber {
            return "#"
        }
        return "#"
    }

    private func getSectionTitle(_ firstChar: String) -> String {
        if firstChar.rangeOfCharacter(from: .letters) != nil {
            return firstChar.uppercased()
        } else if firstChar.rangeOfCharacter(from: .decimalDigits) != nil {
            return "#"
        } else {
            return "#"
        }
    }

    private func sortSections(_ section1: String, _ section2: String) -> Bool {
        if section1 == "#" && section2 != "#" {
            return false
        } else if section1 != "#" && section2 == "#" {
            return true
        } else {
            return section1 < section2
        }
    }

    private func getChinesePinyinFirstLetter(_ chinese: String) -> String {
        guard let firstChar = chinese.first else { return "#" }
        if let cached = AZOrderedListView.pinyinCache[firstChar] {
            return cached
        }
        let pinyinFirstLetters: [Character] = Array(
            "")
        let hanziStart: UInt32 = 19968
        let hanziCount = pinyinFirstLetters.count
        let unicodeValue = firstChar.unicodeScalars.first?.value ?? 0
        if unicodeValue >= hanziStart && unicodeValue < hanziStart + UInt32(hanziCount) {
            let index = Int(unicodeValue - hanziStart)
            if index >= 0 && index < hanziCount {
                let pinyinLetter = pinyinFirstLetters[index]
                let result = String(pinyinLetter).uppercased()
                AZOrderedListView.addToPinyinCache(firstChar, result)
                return result
            }
        }
        let result = "#"
        AZOrderedListView.addToPinyinCache(firstChar, result)
        return result
    }

    private static func clearPinyinCache() {
        pinyinCache.removeAll()
    }

    private static func addToPinyinCache(_ char: Character, _ pinyin: String) {
        if pinyinCache.count >= maxCacheSize {
            let keysToRemove = Array(pinyinCache.keys.prefix(maxCacheSize / 2))
            for key in keysToRemove {
                pinyinCache.removeValue(forKey: key)
            }
        }
        pinyinCache[char] = pinyin
    }
}

private struct AZOrderedListCell: View {
    @EnvironmentObject var themeState: ThemeState
    let user: AZOrderedListItem
    var showsDivider: Bool = true
    let onItemClick: () -> Void

    var body: some View {
        Button(action: onItemClick) {
            HStack(spacing: CGFloat(SpacingScheme.iconIconSpacing)) {
                AvatarView(
                    url: user.avatarURL,
                    name: user.title ?? user.id,
                    shape: .roundedRectangle,
                    cornerRadius: CGFloat(RadiusScheme.tipsRadius)
                )
                Text(user.title ?? user.id)
                    .font(themeState.fonts.body4Regular)
                    .foregroundColor(themeState.colors.textColorPrimary)
                    .lineLimit(1)
                Spacer(minLength: 0)
            }
            .padding(.horizontal, CGFloat(SpacingScheme.bubbleSpacing))
            .frame(height: 60)
            .background(themeState.colors.bgColorOperate)
        }
        .buttonStyle(PlainButtonStyle())
        .overlay(alignment: .bottom) {
            if showsDivider {
                Rectangle()
                    .fill(themeState.colors.strokeColorSecondary)
                    .frame(height: 0.5)
                    .padding(.leading, 68)
            }
        }
        .id(user.id)
    }
}
